export declare const TYPE_NAME: RegExp;
export declare const FIELD_NAME: RegExp;
export declare const ENUM_VALUE: RegExp;
export declare const PRIMITIVES: readonly ["Date", "DateTime", "Flag", "Number", "String"];
export declare const PRIMITIVE_NAMES: ReadonlySet<string>;
/** Structural words, which the grammar never reads as a separately written subset name. */
export declare const RESERVED_NAMES: ReadonlySet<string>;
/**
 * The name a type implies when none is written: its words joined, with a lowercase first
 * letter. `Author` names `author`, and `Verified User` names `verifiedUser`.
 */
export declare function impliedName(typeName: string): string;
/** A name's identifier in code: its words joined in PascalCase, as `VerifiedUsers`. */
export declare function identifierOf(typeName: string): string;
